AUTRES={"gombessa":GB,"lagon":LA,"alien":AL,"court_circuit":CC,"grand_oral":GO}
GENANT=["BITE","ANUS","SEX","CUL","CON","PUTE","PUTA","NAZI","PENIS","ZIZI","CACA","PIPI","MERDE","NIQUE","NIK","FION","SALOP","BATAR","NEGR","PD","KKK","FDP","TEUB","CHATTE","SEIN","MORT","TUER"]
def lev(a,b):
    d=list(range(len(b)+1))
    for i,ca in enumerate(a,1):
        p,d[0]=d[0],i
        for j,cb in enumerate(b,1):
            p,d[j]=d[j],min(d[j]+1,d[j-1]+1,p+(ca!=cb))
    return d[-1]
def verifier(nom, liste):
    err=[]
    if len(liste)!=64: err.append(f"{len(liste)} mots au lieu de 64")
    if len(set(liste))!=len(liste): err.append("doublons")
    tous=[(a,w) for a,l in AUTRES.items() for w in l]
    for w in liste:
        if not (4<=len(w)<=8 and w.isalpha() and w.isupper() and w.isascii()): err.append(f"forme : {w}")
        if w.startswith(("PROF","GB")): err.append(f"début réservé : {w}")
        for g in GENANT:
            if g in w: err.append(f"suite gênante {g} : {w}")
        for a,x in tous:
            if x==w: err.append(f"déjà dans {a} : {w}")
            elif x.startswith(w) or w.startswith(x): err.append(f"préfixe avec {a}.{x} : {w}")
            elif lev(x,w)<2: err.append(f"trop proche de {a}.{x} : {w}")
    for a,b in itertools.combinations(liste,2):
        if a.startswith(b) or b.startswith(a): err.append(f"préfixe interne : {a}/{b}")
        if lev(a,b)<3: err.append(f"trop proches : {a}/{b}")
    return err
if __name__=="__main__":
    l=open(sys.argv[1]).read().split()
    e=verifier("commun",l)
    print("\n".join(e) if e else f"OK : {len(l)} mots, toutes les règles passent")
